[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'events', 'config': {'args': {
    'model': 'calendar.event',
    'domain': [['start', '>=', '${today_start}'], ['start', '<', '${today_end}']],
    'fields': ['name', 'start', 'partner_ids', 'description'],
    'limit': 10, 'order': 'start asc'}}},
  {'type': 'agent', 'resultVariable': 'brief', 'config': {'instruction': 'For each meeting in ${events}, brief me in two lines: who it is with, and any open sale orders, invoices, or tasks with those partners (search for them). No open items: say so in one line.'}},
  {'type': 'output', 'config': {'value': '${brief}'}}
]

[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'drafts', 'config': {'args': {
    'model': 'account.move',
    'domain': [['move_type', '=', 'in_invoice'], ['state', '=', 'draft']],
    'fields': ['name', 'partner_id', 'amount_total', 'invoice_date'],
    'limit': 15, 'order': 'invoice_date asc'}}},
  {'type': 'agent', 'resultVariable': 'triage', 'config': {'instruction': 'Triage these draft vendor bills in ${drafts}: which are ready to post, and which need a partner or a total first. One line per bill.'}},
  {'type': 'output', 'config': {'value': '${triage}'}}
]
